          .blur(15).margin(10)
      }.width('90%').height(40)
      .backgroundColor(0xF9CF93)
      // Blur the background.
      Text('backdropBlur').fontSize(15).fontColor(0xCCCCCC).width('90%')
      Text()
        .width('90%')
        .height(40)
        .fontSize(16)
        .backdropBlur(3)
